const C_JER  = {COORDINACION:'#06b6d4',DIRECCION:'#f97316',SUBDIRECCION:'#ec4899',GERENCIA:'#10b981',LIDER:'#7c3aed',OPERACION:'#f59e0b',OPERATIVO:'#f59e0b',SUPERVISION:'#ef4444'};
