function getC(pal, key) {
  if (!key) return '#64748b';
  const k = String(key).toUpperCase().trim();
  for (const [pk, v] of Object.entries(pal)) {
    if (k === pk.toUpperCase()) return v;
  }
  return pal.DEFAULT || '#64748b';
}

let rawData = [], bajasData = [], charts = {}, theme = 'dark', lastFile = null, fileHandle = null;

// ══ DETECCIÓN DE TIPO DE ARCHIVO ══
function detectFileType(rows) {
  if (!rows.length) return 'activos';
  const normK = (k) => String(k).normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/[\s_]+/g,'');
  const keysN = Object.keys(rows[0]).map(normK);
  const has = (...candidates) => candidates.some(c => keysN.includes(normK(c)));
  const findKey = (...candidates) => {
    const target = candidates.map(normK);
    return Object.keys(rows[0]).find(k => target.includes(normK(k))) || null;
  };

  // SEÑAL 1: nombre de columna explícito
  const bajasNameSig =
    has('TIPO DE BAJA','TIPO_BAJA','TIPO BAJA','TIPOBAJA') ||
    has('MOTIVO DE BAJA','MOTIVO_BAJA','MOTIVO BAJA','MOTIVOBAJA') ||
    has('COLABORADOR2','COLABORADOR 2') ||
    has('AÑO DE BAJA','ANIO DE BAJA','MES DE BAJA');

  const activosNameSig =
    has('ESTATUS_COLABORADOR','ESTATUS COLABORADOR','ESTATUS') ||
    has('NOMBRE_COMPLETO_COLABORADOR','NOMBRE COMPLETO COLABORADOR') ||
    has('CORREO_CORPORATIVO','CORREO CORPORATIVO');

  if (bajasNameSig && !activosNameSig) return 'bajas';
  if (activosNameSig && !bajasNameSig) return 'activos';

  // SEÑAL 2: contenido — busca valores VOLUNTARIA/INVOLUNTARIA en cualquier columna texto
  const sample = rows.slice(0, Math.min(rows.length, 80));
  let voluntariosVistos = 0;
  for (const r of sample) {
    for (const k of Object.keys(r)) {
      const v = r[k];
      if (typeof v !== 'string') continue;
      const vn = v.normalize('NFD').replace(/[̀-ͯ]/g,'').toUpperCase();
      if (/VOLUNTARI|INVOLUNTARI|RENUNCIA|DESPIDO/.test(vn)) { voluntariosVistos++; break; }
    }
    if (voluntariosVistos >= 3) return 'bajas';
  }

  // SEÑAL 3: cualquier columna que parezca "fecha de baja" o "fecha baja" tiene >50% poblada → bajas
  const bajaCandidates = ['FECHA DE BAJA','FECHA_BAJA','FECHABAJA','F BAJA','FECHA BAJA'];
  const bajaKey = findKey(...bajaCandidates);
  if (bajaKey) {
    const conBaja = rows.filter(r => r[bajaKey] != null && r[bajaKey] !== '').length;
    if (conBaja / rows.length > 0.5) return 'bajas';
  }

  // SEÑAL 4: valores ACTIVO en columna estatus → activos
  const sample2 = rows.slice(0, Math.min(rows.length, 50));
  for (const r of sample2) {
    for (const k of Object.keys(r)) {
      if (!/estat|status/i.test(k)) continue;
      const v = String(r[k] || '').toUpperCase();
      if (v.includes('ACTIVO')) return 'activos';
    }
  }

  return 'activos'; // default
}

// ══ HELPERS rx* — abstraen diferencias entre archivos (tolerantes a acentos/casing) ══
function _normK(k) { return String(k).normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/[\s_]+/g,''); }
// Cache global de candidatos normalizados (mismas strings literales se repiten miles de veces)
const _candCache = new Map();
function _normCand(c) {
  let v = _candCache.get(c);
  if (v === undefined) { v = _normK(c); _candCache.set(c, v); }
  return v;
}
// Construye/recupera mapa de keys-normalizadas → key-original por fila (cacheado en r.__nk)
function _rowKeyMap(r) {
  let m = r.__nk;
  if (m === undefined) {
    m = Object.create(null);
    for (const k of Object.keys(r)) {
      if (k.charCodeAt(0) === 95) continue; // saltarse keys internas (_fi, _fb, _src, etc.)
      const nk = _normK(k);
      if (m[nk] === undefined) m[nk] = k; // primera columna gana (preserva orden del archivo)
    }
    r.__nk = m;
  }
  return m;
}
function rxGet(r, ...candidates) {
  if (!r) return null;
  // Iterar CANDIDATOS en orden — el primer candidato con valor no vacío gana.
  // Lookup O(1) por candidato gracias a los caches.
  const map = _rowKeyMap(r);
  for (const cand of candidates) {
    const key = map[_normCand(cand)];
    if (key !== undefined) {
      const v = r[key];
      if (v != null && v !== '') return v;
    }
  }
  return null;
}
function rxId(r) { return rxGet(r, 'ID_C', 'ID'); }
function rxNombre(r) {
  if (!r) return '';
  if (r._nombre !== undefined) return r._nombre || '(Sin nombre)'; // cache (precomputado)
  const f = (rxGet(r, 'NOMBRE_COMPLETO_COLABORADOR', 'COLABORADOR2', 'COLABORADOR', 'NOMBRE COMPLETO') || '').toString().trim();
  if (f) return f;
  const n  = (rxGet(r, 'NOMBRE(S)', 'NOMBRES', 'NOMBRE') || '').toString().trim();
  const ap = (rxGet(r, 'A_PATERNO', 'APELLIDO PATERNO', 'APELLIDO_PATERNO') || '').toString().trim();
  const am = (rxGet(r, 'A_MATERNO', 'APELLIDO MATERNO', 'APELLIDO_MATERNO') || '').toString().trim();
  return [n, ap, am].filter(Boolean).join(' ') || '(Sin nombre)';
}
function rxPuesto(r) { return ((rxGet(r, 'PUESTO_COLABORADOR', 'PUESTO') || '')+'').trim(); }
function rxFechaIngreso(r) {
  if (r && r._fi !== undefined) return r._fi; // cache
  return pDate(rxGet(r, 'FECHA_INGRESO', 'FECHA DE INGRESO', 'FECHA INGRESO', 'Personalizado'));
}
function rxFechaBaja(r) {
  if (r && r._fb !== undefined) return r._fb; // cache
  return pDate(rxGet(r, 'FECHA_BAJA', 'FECHA DE BAJA', 'FECHA BAJA'));
}
// Pre-procesa fechas + clasificación VOL/INV. Cache en _fi/_fb/_tipo/_vol/_inv/_sede/_empresa
function precomputeDates(rows) {
  let okFi = 0, okFb = 0, totFi = 0, totFb = 0;
  for (const r of rows) {
    const vi = rxGet(r, 'FECHA_INGRESO', 'FECHA DE INGRESO', 'FECHA INGRESO', 'Personalizado');
    const vb = rxGet(r, 'FECHA_BAJA', 'FECHA DE BAJA', 'FECHA BAJA');
    if (vi != null && vi !== '') totFi++;
    if (vb != null && vb !== '') totFb++;
    r._fi = pDate(vi) || null;
    r._fb = pDate(vb) || null;
    if (r._fi) okFi++;
    if (r._fb) okFb++;
    // Cache de clasificación (evita recalcular rxGet/regex en cada filter de chart)
    const tipoRaw = rxGet(r, 'TIPO DE BAJA','TIPO_BAJA','TIPO BAJA','MOTIVO DE BAJA','MOTIVO_BAJA','MOTIVO BAJA','RAZON DE BAJA','RAZON_BAJA','RAZON BAJA');
    const t = tipoRaw ? norm(tipoRaw) : null;
    r._tipo = t;
    if (!t) {
      r._vol = null; r._inv = null;
    } else if (/INVOLUNTAR/.test(t)) {
      r._vol = false; r._inv = true;
    } else if (VOL_RE.test(t)) {
      r._vol = true; r._inv = false;
    } else if (INV_RE.test(t)) {
      r._vol = false; r._inv = true;
    } else {
      r._vol = false; r._inv = false;
    }
    // Cache de sede y empresa (norm es relativamente caro)
    r._sede = norm(rxGet(r, 'SEDE'));
    r._empresa = norm(rxGet(r, 'EMPRESA'));
    // Canonicaliza columnas cuyo nombre cambió entre versiones del Excel (p.ej. ESTATUS vs
    // ESTATUS_COLABORADOR, NIVEL_JERARQUICO vs NIVEL_JERARQUIA), para que el código que accede
    // a r['CAMPO'] directamente (fuera de rxGet) siga funcionando con cualquier formato.
    r['ESTATUS_COLABORADOR']      = rxGet(r, 'ESTATUS_COLABORADOR', 'ESTATUS COLABORADOR', 'ESTATUS');
    r['NIVEL_JERARQUIA']          = rxGet(r, 'NIVEL_JERARQUIA', 'NIVEL JERARQUICO', 'NIVEL JERARQUIA', 'NIVEL_JERARQUICO');
    r['ADMINISTRADORA DE NOMINA'] = rxGet(r, 'ADMINISTRADORA DE NOMINA', 'ADMINISTRADORA DE NÓMINA', 'ADMINSTRADORA DE NOMINA', 'ADMINSTRADORA DE NÓMINA');
    // HRBP reemplazó a LOCAL/FORANEO en el Excel — mismo campo, nombre y contenido nuevos.
    r['HRBP'] = rxGet(r, 'HRBP', 'LOCAL/FORANEO', 'LOCAL/FORÁNEO', 'LOCAL FORANEO');
    // Cache del nombre completo + versión normalizada para búsqueda (pdSearch usa esto en cada keystroke)
    const fullN = (rxGet(r, 'NOMBRE_COMPLETO_COLABORADOR', 'COLABORADOR2', 'COLABORADOR', 'NOMBRE COMPLETO') || '').toString().trim();
    if (fullN) {
      r._nombre = fullN;
    } else {
      const n  = (rxGet(r, 'NOMBRE(S)', 'NOMBRES', 'NOMBRE') || '').toString().trim();
      const ap = (rxGet(r, 'A_PATERNO', 'APELLIDO PATERNO', 'APELLIDO_PATERNO') || '').toString().trim();
      const am = (rxGet(r, 'A_MATERNO', 'APELLIDO MATERNO', 'APELLIDO_MATERNO') || '').toString().trim();
      r._nombre = [n, ap, am].filter(Boolean).join(' ');
    }
    r._nombreNorm = r._nombre ? r._nombre.normalize('NFD').replace(/[̀-ͯ]/g,'').toUpperCase().trim() : '';
  }
  return { okFi, totFi, okFb, totFb };
}
function rxJefe(r) { return ((rxGet(r, 'JEFE_DIRECTO', 'LIDER', 'LIDER DIRECTO', 'JEFE') || '')+'').trim(); }
function rxArea(r) { return norm(rxGet(r, 'AREA', 'ÁREA')); }
function rxHRBP(r) { return norm(rxGet(r, 'HRBP', 'LOCAL/FORANEO', 'LOCAL/FORÁNEO', 'LOCAL FORANEO')); }
function rxSueldo(r) {
  const v = rxGet(r, 'SUELDO MENSUAL MX', 'SUELDO MESUAL BRUTOS MX', 'SUELDO MENSUAL BRUTOS MX', 'SUELDO');
  if (v == null || v === '') return 0;
  const n = typeof v === 'number' ? v : Number(String(v).replace(/[^0-9.\-]/g,''));
  return isNaN(n) ? 0 : n;
}
function rxNivelJer(r) { return norm(rxGet(r, 'NIVEL_JERARQUIA', 'NIVEL JERARQUICO', 'NIVEL JERARQUIA', 'NIVEL_JERARQUICO')); }
function rxSede(r) { if (r && r._sede !== undefined) return r._sede; return norm(rxGet(r, 'SEDE')); }
function rxEmpresa(r) { if (r && r._empresa !== undefined) return r._empresa; return norm(rxGet(r, 'EMPRESA')); }
function rxGeneracion(r) { return norm(rxGet(r, 'GENERACION', 'GENERACIÓN')); }
function rxDepartamento(r) { return norm(rxGet(r, 'DEPARTAMENTO')); }
function rxTipoBaja(r) { return norm(rxGet(r, 'TIPO DE BAJA', 'TIPO_BAJA', 'TIPO BAJA')); }
function rxMotivoBaja(r) { return ((rxGet(r, 'MOTIVO DE BAJA', 'MOTIVO_BAJA', 'MOTIVO BAJA') || '')+'').trim(); }

// Busca un registro en rawData por su ID_C (relación entre tablas)
function findActivoById(idc) {
  if (!idc) return null;
  const key = String(idc).trim();
  return rawData.find(r => String(rxId(r)||'').trim() === key) || null;
}
function findBajaById(idc) {
  if (!idc) return null;
  const key = String(idc).trim();
  return bajasData.find(r => String(rxId(r)||'').trim() === key) || null;
}
// Determina si un empleado está ACTIVO o BAJA usando el marcador _src
function rxEstatus(r) {
  if (!r) return 'ACTIVO';
  // Marca del archivo de origen (puesta al cargar)
  if (r._src === 'bajas') return 'BAJA';
  if (r._src === 'activos') return 'ACTIVO';
  // Fallback para registros sin _src
  if (rxFechaBaja(r)) return 'BAJA';
  const est = norm(rxGet(r, 'ESTATUS_COLABORADOR', 'ESTATUS COLABORADOR', 'ESTATUS'));
  if (est && /BAJA/.test(est)) return 'BAJA';
  return 'ACTIVO';
}

// ══ FECHA AUTOMÁTICA ══
function setFecha() {
  const now = new Date();
  const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
  const txt = `${now.getDate()} de ${meses[now.getMonth()]} de ${now.getFullYear()}`;
  const el = document.getElementById('fechaHoy');
  if (el) el.textContent = txt;
  const yrEl = document.getElementById('appFooterYr');
  if (yrEl) yrEl.textContent = '© ' + now.getFullYear();
}

function validateFileShape(rows, fileType) {
  if (!rows.length) return { ok: false, reason: 'Archivo vacío.' };
  const keysN = Object.keys(rows[0]).map(_normK);
  const has = (...candidates) => candidates.some(c => keysN.includes(_normK(c)));
  if (fileType === 'bajas') {
    // Para bajas necesitamos al menos: identificador + alguna columna de baja
    const tieneId = has('ID_C','ID');
    const tieneAlgoBaja =
      has('FECHA DE BAJA','FECHA_BAJA','FECHA BAJA') ||
      has('TIPO DE BAJA','TIPO_BAJA','TIPO BAJA') ||
      has('MOTIVO DE BAJA','MOTIVO_BAJA','MOTIVO BAJA') ||
      has('COLABORADOR2','COLABORADOR 2') ||
      has('AÑO DE BAJA','ANIO DE BAJA');
    if (!tieneId || !tieneAlgoBaja) {
      return { ok: false, reason: 'No parece archivo de bajas: falta ID_C y/o columnas como FECHA DE BAJA, TIPO DE BAJA, COLABORADOR2. Verifica que sea el archivo correcto.' };
    }
  } else if (fileType === 'activos') {
    const tieneId = has('ID_C','ID');
    const tieneAlgoActivo =
      has('ESTATUS_COLABORADOR','ESTATUS COLABORADOR','ESTATUS') ||
      has('NOMBRE_COMPLETO_COLABORADOR','NOMBRE COMPLETO','NOMBRE COMPLETO COLABORADOR') ||
      has('CORREO_CORPORATIVO','CORREO CORPORATIVO') ||
      has('FECHA_INGRESO','FECHA DE INGRESO');
    if (!tieneId || !tieneAlgoActivo) {
      return { ok: false, reason: 'No parece archivo de empleados activos: falta ID_C y/o columnas como ESTATUS, NOMBRE COMPLETO, FECHA DE INGRESO. Verifica que sea el archivo correcto.' };
    }
  }
  return { ok: true };
}

function showToast(msg, type) {
  let host = document.getElementById('toastHost');
  if (!host) {
    host = document.createElement('div');
    host.id = 'toastHost';
    host.className = 'toast-host';
    document.body.appendChild(host);
  }
  const t = document.createElement('div');
  t.className = 'toast ' + (type || 'info');
  t.innerHTML = msg + '<button type="button" class="toast-x" aria-label="Cerrar">&times;</button>';
  host.appendChild(t);
  const duration = type === 'error' ? 14000 : 6000;
  const closeBtn = t.querySelector('.toast-x');
  if (closeBtn) closeBtn.addEventListener('click', () => { t.classList.add('toast-out'); setTimeout(() => t.remove(), 350); });
  setTimeout(() => { if (t.parentNode) { t.classList.add('toast-out'); setTimeout(() => t.remove(), 350); } }, duration);
}

// Función centralizada para leer un File object y cargar datos
// forcedType opcional: 'activos' | 'bajas' (omite auto-detección)
function readAndLoadFile(file, forcedType) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = function(e) {
      try {
        let wb;
        if (e.target.result instanceof ArrayBuffer) {
          wb = XLSX.read(new Uint8Array(e.target.result), { type:'array', cellDates:true });
        } else {
          wb = XLSX.read(e.target.result, { type:'binary', cellDates:true });
        }
        console.group('[Carga Excel] ' + file.name);
        console.log('Hojas disponibles:', wb.SheetNames);
        const ws = wb.Sheets[wb.SheetNames[0]];
        const rows = XLSX.utils.sheet_to_json(ws, { defval:null });
        console.log('Filas leídas:', rows.length);
        if (rows.length > 0) {
          console.log('Columnas detectadas:', Object.keys(rows[0]));
          console.log('Primer registro:', rows[0]);
        }
        if (!rows.length) { console.groupEnd(); throw new Error('Archivo vacío'); }
        const fileType = forcedType || detectFileType(rows);
        console.log('→ Tipo aplicado:', fileType, forcedType ? '(forzado por usuario)' : '(auto-detección)');
        console.groupEnd();

        // Validación: el archivo tiene las columnas mínimas esperadas para el tipo elegido
        const valid = validateFileShape(rows, fileType);
        if (!valid.ok) {
          showToast(
            `<b>❌ Archivo no compatible</b><br/>` +
            `<small>${file.name}</small><br/>` +
            `<b>${rows.length}</b> filas · <b>${Object.keys(rows[0]).length}</b> cols<br/>` +
            `<small>Columnas encontradas: ${Object.keys(rows[0]).slice(0,4).join(', ')}…</small><br/>` +
            `<span class="toast-warn">${valid.reason}</span>`,
            'error'
          );
          throw new Error(valid.reason);
        }

        // Toast de feedback con resumen
        const cols = Object.keys(rows[0]);
        const sample = cols.slice(0, 4).join(', ');
        const typeLbl = fileType === 'bajas' ? '📉 BAJAS' : '👥 ACTIVOS';
        const warn = rows.length < 20 ? ' <span class="toast-warn">⚠ pocas filas</span>' : '';
        showToast(
          `<b>${typeLbl}</b>${warn}<br/>` +
          `<small>${file.name}</small><br/>` +
          `<b>${rows.length}</b> filas · <b>${cols.length}</b> columnas<br/>` +
          `<small>${sample}…</small>`,
          rows.length < 20 ? 'warn' : 'success'
        );
        const dateStats = precomputeDates(rows);
        // Marca cada fila con su archivo de origen para detección rápida de estatus
        for (const r of rows) r._src = fileType;

        if (fileType === 'bajas') {
          bajasData = rows;
          updateDataChip();
          if (rawData.length && currentView === 'rotacion') renderRotacionView();
          if (rawData.length && currentView === 'altas') renderAltasView();
          const okFb = dateStats.okFb, totFb = dateStats.totFb;
          if (totFb > 0 && okFb < totFb) {
            const fallidas = totFb - okFb;
            showToast(
              `<b>⚠ Fechas no parseadas</b><br/>` +
              `<small>${fallidas} de ${totFb} 'FECHA DE BAJA' no se pudieron leer.</small><br/>` +
              `<small>Revisa el formato (debe ser dd/mm/yyyy o fecha de Excel)</small>`,
              'warn'
            );
          }
        } else {
          // En el archivo de activos, descartar cualquier registro que parezca baja
          const activosFiltrados = rows.filter(r => {
            if (r._fb) return false; // tiene FECHA_BAJA → baja
            const est = norm(rxGet(r, 'ESTATUS_COLABORADOR', 'ESTATUS COLABORADOR', 'ESTATUS'));
            if (est && /BAJA/.test(est)) return false;
            return true;
          });
          const descartados = rows.length - activosFiltrados.length;
          rawData = activosFiltrados;
          setFecha(); fillFilters(); rebuildAll();
          updateDataChip();
          if (descartados > 0) {
            showToast(
              `<b>👥 Activos cargados</b><br/>` +
              `<small><b>${activosFiltrados.length}</b> activos · <b>${descartados}</b> registros de baja ignorados</small>`,
              'info'
            );
          }
        }
        resolve(fileType);
      } catch(err) { reject(err); }
    };
    reader.onerror = () => reject(new Error('Error al leer el archivo'));
    try { reader.readAsArrayBuffer(file); } catch(e) { reader.readAsBinaryString(file); }
  });
}

// Chip indicador de archivos cargados (clickeable para ver detalle)
function updateDataChip() {
  const el = document.getElementById('dataChip');
  if (!el) return;
  const a = rawData.length;
  const b = bajasData.length;
  el.innerHTML = `
    <span class="data-chip-item ${a ? '' : 'off'}" title="Activos cargados">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
      ${a ? a : '—'}
    </span>
    <span class="data-chip-item ${b ? '' : 'off'}" title="Bajas cargadas">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="23 18 13.5 8.5 8.5 13.5 1 6"/><polyline points="17 18 23 18 23 12"/></svg>
      ${b ? b : '—'}
    </span>
  `;
  el.classList.toggle('hidden', !(a || b));
  el.onclick = showDataChipDetail;
}

function showDataChipDetail() {
  const a = rawData.length, b = bajasData.length;
  let partA = a
    ? `👥 ACTIVOS\n  Total: ${a}\n  Columnas: ${Object.keys(rawData[0]).length}`
    : '👥 ACTIVOS\n  (vacío)';

  // Diagnóstico detallado de BAJAS
  let partB;
  if (b) {
    // Bajas por año (según FECHA DE BAJA parseada)
    const porAnio = {};
    let sinFecha = 0, sinSede = 0, sinTipoBaja = 0;
    let conColAnio = 0;
    const tieneColAnio = bajasData[0].hasOwnProperty('AÑO DE BAJA') || bajasData[0].hasOwnProperty('ANIO DE BAJA');
    const porAnioColumna = {};
    let mismatchAnio = 0;

    for (const r of bajasData) {
      const d = rxFechaBaja(r);
      if (!d) { sinFecha++; }
      else {
        const y = d.getFullYear();
        porAnio[y] = (porAnio[y] || 0) + 1;
      }
      if (!rxSede(r)) sinSede++;
      if (!getTipoBaja(r)) sinTipoBaja++;
      // Comparar año de columna AÑO DE BAJA vs FECHA DE BAJA
      const colAnio = rxGet(r, 'AÑO DE BAJA', 'ANIO DE BAJA');
      if (colAnio != null && colAnio !== '') {
        conColAnio++;
        const yCol = Number(colAnio);
        porAnioColumna[yCol] = (porAnioColumna[yCol] || 0) + 1;
        if (d && d.getFullYear() !== yCol) mismatchAnio++;
      }
    }

    const anioLines = Object.keys(porAnio).sort().map(y => `    ${y}: ${porAnio[y]}`).join('\n') || '    (ninguno parseable)';
    let extra = '';
    if (tieneColAnio) {
      const colLines = Object.keys(porAnioColumna).sort().map(y => `    ${y}: ${porAnioColumna[y]}`).join('\n');
      extra = `\n  Según columna AÑO DE BAJA (${conColAnio} con valor):\n${colLines}`;
      if (mismatchAnio > 0) extra += `\n  ⚠ ${mismatchAnio} filas con AÑO DE BAJA ≠ año de FECHA DE BAJA`;
    }

    // Conteo por SEDE
    const porSede = {};
    for (const r of bajasData) {
      const s = rxSede(r) || '(vacía)';
      porSede[s] = (porSede[s] || 0) + 1;
    }
    const sedeLines = Object.entries(porSede).sort((a,c)=>c[1]-a[1]).map(([s,n]) => `    "${s}" (${s.length} chars): ${n}`).join('\n');

    partB =
      `📉 BAJAS\n` +
      `  Total: ${b}\n` +
      `  Columnas: ${Object.keys(bajasData[0]).length}\n` +
      `  Por año (FECHA DE BAJA parseada):\n${anioLines}\n` +
      `  ${sinFecha > 0 ? '⚠' : '✓'} ${sinFecha} sin FECHA DE BAJA parseable\n` +
      `  ${sinSede > 0 ? '⚠' : '✓'} ${sinSede} sin SEDE\n` +
      `  ${sinTipoBaja > 0 ? '⚠' : '✓'} ${sinTipoBaja} sin TIPO DE BAJA${extra}\n` +
      `  SEDES detectadas (con count global):\n${sedeLines}`;
  } else {
    partB = '📉 BAJAS\n  (vacío)';
  }

  const msg =
    'ARCHIVOS CARGADOS\n\n' + partA + '\n\n' + partB + '\n\n' +
    '— ACCIONES —\n' +
    'A) Pasar contenido de ACTIVOS → BAJAS\n' +
    'B) Pasar contenido de BAJAS → ACTIVOS\n' +
    'C) Limpiar BAJAS\n' +
    'D) Limpiar ACTIVOS\n' +
    'X) Cerrar\n\n' +
    'Escribe A, B, C, D o X:';

  const resp = (prompt(msg, 'X') || '').toUpperCase().trim();
  if (resp === 'A') {
    if (!a) return;
    bajasData = rawData.slice();
    rawData = [];
  } else if (resp === 'B') {
    if (!b) return;
    rawData = bajasData.slice();
    bajasData = [];
    setFecha(); fillFilters(); rebuildAll();
  } else if (resp === 'C') {
    bajasData = [];
  } else if (resp === 'D') {
    rawData = [];
  } else {
    return;
  }
  updateDataChip();
  if (currentView === 'rotacion') renderRotacionView();
  if (currentView === 'altas') renderAltasView();
}

// ══ FONT SIZE TOGGLE ══
let fontLg = false;
// Helper: retorna tamaño de fuente escalado según modo accesibilidad
