// ══ DRAG & DROP ══
const dz  = document.getElementById('dropzone');
const fi  = document.getElementById('fileInput');

// Función para abrir archivo — usa File System Access API si está disponible
async function openFilePicker() {
  if (window.showOpenFilePicker) {
    try {
      const [handle] = await window.showOpenFilePicker({
        types:[{ description:'Excel', accept:{'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':['.xlsx','.xls']} }],
        multiple: false
      });
      fileHandle = handle;
      const file = await handle.getFile();
      lastFile = file;
      processFile(file);
      return;
    } catch(e) {
      if (e.name === 'AbortError') return; // usuario canceló
    }
  }
  // Fallback a input[type=file] clásico
  fi.click();
}

dz.addEventListener('dragover', e => { e.preventDefault(); dz.classList.add('over'); });
dz.addEventListener('dragleave', () => dz.classList.remove('over'));
dz.addEventListener('drop', e => {
  e.preventDefault(); dz.classList.remove('over');
  if (e.dataTransfer.files[0]) processFile(e.dataTransfer.files[0]);
});
document.getElementById('dzSpan').addEventListener('click', e => { e.preventDefault(); e.stopPropagation(); openFilePicker(); });
document.getElementById('dzBtn').addEventListener('click',  e => { e.preventDefault(); e.stopPropagation(); openFilePicker(); });
fi.addEventListener('change', function() { if (this.files && this.files[0]) { fileHandle = null; lastFile = this.files[0]; processFile(this.files[0]); } });
function handleChange(input, forcedType) {
  if (input.files && input.files[0]) {
    fileHandle = null;
    lastFile = input.files[0];
    processFile(input.files[0], forcedType);
    // limpiar para que se pueda recargar el mismo archivo después
    input.value = '';
  }
}

// ══ PROCESAR ARCHIVO ══
function processFile(file, forcedType) {
  if (typeof XLSX === 'undefined') { alert('Librerías no cargadas. Verifica conexión y recarga.'); return; }
  lastFile = file;
  document.getElementById('dzFname').textContent = '⏳ Cargando ' + file.name + '...';
  // Overlay visible durante TODO el flow: parseo del Excel + precompute + render del dashboard
  const lblMap = { bajas: 'Cargando bajas…', activos: 'Cargando activos…' };
  showLoading(lblMap[forcedType] || `Cargando ${file.name}…`);
  readAndLoadFile(file, forcedType).then((fileType) => {
    if (fileType === 'bajas' && !rawData.length) {
      hideLoading();
      document.getElementById('dzFname').textContent = `📉 ${bajasData.length} bajas cargadas. Ahora carga el archivo de Activos para ver el dashboard.`;
      return;
    }
    // Esperar un frame para que el label "Cargando…" sea visible antes del trabajo síncrono
    requestAnimationFrame(() => requestAnimationFrame(() => {
      try { showDashboard(); } finally { hideLoading(); }
    }));
  }).catch(err => {
    hideLoading();
    alert('Error al procesar: ' + err.message);
    document.getElementById('dzFname').textContent = '❌ ' + err.message;
  });
}

function showDashboard() {
  document.getElementById('uploadScreen').classList.add('hidden');
  const app = document.getElementById('app');
  app.style.display = 'flex';
  setTimeout(() => app.classList.add('visible'), 10);
  setLogos();
  setFecha();
  fillFilters();
  rebuildAll();
  setTimeout(() => { initKpiDrag(); initChartDrag(); }, 200);
}

// ══ FILTROS ══
function fillFilters() {
  const act = rawData.filter(r => norm(r['ESTATUS_COLABORADOR']) === 'ACTIVO');
  const fill = (id, field) => {
    const sel = document.getElementById(id);
    const prev = sel.value;
    const vals = [...new Set(act.map(r => norm(r[field])).filter(Boolean))].sort();
    sel.innerHTML = '<option value="">Todas</option>' + vals.map(v => `<option>${v}</option>`).join('');
    if (vals.includes(prev)) sel.value = prev;
  };
  fill('fSede','SEDE'); fill('fGen','GENERACION'); fill('fEmp','EMPRESA'); fill('fArea','AREA'); fill('fHRBP','HRBP');
}
['fSede','fGen','fEmp','fGenero','fHRBP','fArea'].forEach(id =>
  document.getElementById(id).addEventListener('change', () => { if (rawData.length) rebuildAllDeferred('Aplicando filtros…'); })
);
// ══ CROSS-FILTER STATE ══
const CF = {
  SEDE: null, GENERO: null, GENERACION: null,
  NIVEL_JERARQUIA: null, EMPRESA: null, NOMINA: null, ANTIG: null, AREA: null
};

function setCF(field, value) {
  CF[field] = CF[field] === value ? null : value; // toggle
  rebuildAllDeferred('Aplicando filtro…');
  updateCFUI();
}

function clearAllCF() {
  Object.keys(CF).forEach(k => CF[k] = null);
  rebuildAllDeferred('Limpiando selección…');
  updateCFUI();
}

function updateCFUI() {
  const active = Object.values(CF).filter(v => v !== null);
  const btn   = document.getElementById('cfClearBtn');
  const badge = document.getElementById('cfBadge');
  if (!btn || !badge) return;
  if (active.length) {
    btn.style.display   = 'inline-flex';
    badge.textContent   = active.length;
    badge.style.display = 'inline-flex';
  } else {
    btn.style.display   = 'none';
    badge.style.display = 'none';
  }
}

function getFiltered() {
  const fS = document.getElementById('fSede').value;
  const fG = document.getElementById('fGen').value;
  const fE = document.getElementById('fEmp').value;
  const fN = document.getElementById('fGenero').value;
  const fH = document.getElementById('fHRBP').value;
  const fAr = document.getElementById('fArea').value;
  return rawData.filter(r => {
    if (norm(r['ESTATUS_COLABORADOR']) !== 'ACTIVO') return false;
    if (fS && norm(r['SEDE'])       !== fS) return false;
    if (fG && norm(r['GENERACION']) !== fG) return false;
    if (fE && norm(r['EMPRESA'])    !== fE) return false;
    if (fN && norm(r['GENERO'])     !== fN) return false;
    if (fH && rxHRBP(r)             !== fH) return false;
    if (fAr && norm(r['AREA'])      !== fAr) return false;
    // Cross-filters desde gráficas
    if (CF.SEDE         && norm(r['SEDE'])                       !== CF.SEDE)         return false;
    if (CF.GENERO       && norm(r['GENERO'])                     !== CF.GENERO)       return false;
    if (CF.GENERACION   && norm(r['GENERACION'])                 !== CF.GENERACION)   return false;
    if (CF.NIVEL_JERARQUIA && norm(r['NIVEL_JERARQUIA'])         !== CF.NIVEL_JERARQUIA) return false;
    if (CF.EMPRESA      && norm(r['EMPRESA'])                    !== CF.EMPRESA)      return false;
    if (CF.NOMINA       && norm(r['ADMINISTRADORA DE NOMINA'])   !== CF.NOMINA)       return false;
    if (CF.ANTIG        && getRangoAntig(r)                      !== CF.ANTIG)        return false;
    if (CF.AREA         && norm(r['AREA'])                       !== CF.AREA)         return false;
    return true;
  });
}

// ══ HELPERS ══
// norm: quita espacios invisibles (NBSP, ZWSP, BOM) y normaliza a UPPERCASE trimmed
function norm(v) {
  if (!v) return '';
  return String(v)
    .replace(/[ ​‌‍﻿]/g, '') // NBSP, ZWSP, ZWNJ, ZWJ, BOM
    .replace(/\s+/g, ' ')                              // colapsa espacios múltiples
    .trim()
    .toUpperCase();
}
function pDate(v) {
  if (!v) return null;
  if (v instanceof Date) return isNaN(v.getTime()) ? null : v;
  const s = String(v).trim();
  if (!s) return null;
  // Formato latino dd/mm/yyyy o dd-mm-yyyy (también dd/mm/yy)
  const lat = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/);
  if (lat) {
    let d = Number(lat[1]);
    let mo = Number(lat[2]);
    let y = Number(lat[3]);
    if (y < 100) y += 2000;
    // Validación básica: día 1-31, mes 1-12
    if (d >= 1 && d <= 31 && mo >= 1 && mo <= 12 && y >= 1900 && y <= 2100) {
      const dt = new Date(y, mo - 1, d);
      if (!isNaN(dt.getTime())) return dt;
    }
  }
  // Formato ISO o cualquier otro que Date entienda
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}
function isActiveAt(r, eom) {
  // Usa el cache _fi/_fb si existe (poblado por precomputeDates al cargar archivo)
  const ing  = r._fi !== undefined ? r._fi : pDate(r['FECHA_INGRESO'] || r['Personalizado']);
  const baja = r._fb !== undefined ? r._fb : pDate(r['FECHA_BAJA']);
  if (!ing || ing > eom) return false;
  if (baja && baja <= eom) return false;
  return true;
}
const MESES = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
function fmtM(y,m) { return MESES[m] + ' ' + String(y).slice(2); }
function last13() {
  const now = new Date();
  return Array.from({length:13}, (_,i) => {
    const d = new Date(now.getFullYear(), now.getMonth()-12+i, 1);
    return {year:d.getFullYear(), month:d.getMonth()};
  });
}
function countBy(arr, field) {
  return arr.reduce((a,r) => { const k=norm(r[field]); if(k) a[k]=(a[k]||0)+1; return a; }, {});
}
function pct(n,t) { return t ? Math.round(n/t*100)+'%' : '0%'; }
function dominant(obj) { return Object.entries(obj).sort((a,b)=>b[1]-a[1])[0] || ['–',0]; }
function setText(id,v) { const e=document.getElementById(id); if(e) e.textContent=v; }
function destroyC(id) { if(charts[id]){try{charts[id].destroy();}catch(e){} delete charts[id];} }

// ══ RANGO ANTIGÜEDAD ══
function getRangoAntig(r) {
  // Check dedicated columns first (tolerante a variantes con rxGet)
  const rango = rxGet(r, 'RANGO_ANTIGUEDAD', 'RANGO ANTIGÜEDAD', 'RANGO ANTIGUEDAD', 'Rango Antigüedad', 'RANGO_ANTIG');
  if (rango) return norm(rango);
  // Calcular desde FECHA_INGRESO (usa cache _fi para velocidad y soporta ambos formatos de archivo)
  const ing = rxFechaIngreso(r);
  if (!ing) return null;
  const years = (new Date() - ing) / (1000 * 60 * 60 * 24 * 365.25);
  if (years < 1)   return '0 AÑOS';
  if (years < 3)   return '1 - 2 AÑOS';
  if (years < 6)   return '3 - 5 AÑOS';
  if (years < 16)  return '6 - 15 AÑOS';
  return '16 AÑOS O MÁS';
}

// ══ TOOLTIP STATS HELPERS ══
function ttProm(rows, field) {
  let s = 0, c = 0;
  for (const r of rows) {
    const v = r[field];
    if (v == null || v === '') continue;
    const n = typeof v === 'number' ? v : Number(String(v).replace(/[^0-9.\-]/g,''));
    if (isFinite(n)) { s += n; c++; }
  }
  return c ? s / c : null;
}
function ttAntigProm(rows) {
  const now = new Date();
  let s = 0, c = 0;
  for (const r of rows) {
    const d = pDate(r['FECHA_INGRESO'] || r['Personalizado']);
    if (!d) continue;
    s += (now - d) / (1000 * 60 * 60 * 24 * 365.25);
    c++;
  }
  return c ? s / c : null;
}
function ttDom(rows, field) {
  const c = countBy(rows, field);
  const top = Object.entries(c).sort((a,b)=>b[1]-a[1])[0];
  return top ? top[0] : null;
}
function ttMixHM(rows) {
  const h = rows.filter(r => norm(r['GENERO']) === 'H').length;
  const m = rows.filter(r => norm(r['GENERO']) === 'M').length;
  const t = h + m;
  if (!t) return null;
  return `${Math.round(h/t*100)}% H · ${Math.round(m/t*100)}% M`;
}
function ttFmtNum(n, suffix) {
  if (n == null) return null;
  return n.toFixed(1).replace(/\.0$/,'') + (suffix || '');
}
function ttRangoEdad(rows) {
  let min = Infinity, max = -Infinity;
  for (const r of rows) {
    const v = r['EDAD'];
    const n = typeof v === 'number' ? v : Number(String(v||'').replace(/[^0-9.\-]/g,''));
    if (isFinite(n) && n > 0) {
      if (n < min) min = n;
      if (n > max) max = n;
    }
  }
  if (!isFinite(min)) return null;
  return min === max ? `${min} años` : `${min}–${max} años`;
}
function buildMonthStats(year, month, baseData) {
  const start = new Date(year, month, 1);
  const eom = new Date(year, month + 1, 0);
  let altas = 0, bajas = 0;
  for (const r of baseData) {
    const di = pDate(r['FECHA_INGRESO'] || r['Personalizado']);
    if (di && di >= start && di <= eom) altas++;
    const db = pDate(r['FECHA_BAJA']);
    if (db && db >= start && db <= eom) bajas++;
  }
  return { altas, bajas };
}

// ══ REBUILD ══
// rebuildAll síncrono — usado para el primer render al cargar datos
function rebuildAll() {
  const data = getFiltered();
  renderKPIs(data);
  renderSidebar(data);
  renderGeneralMes(data);
  renderHCSede(data);
  renderDonaSede(data);
  renderAreaChart(data);
  renderGenGenero(data);
  renderGeneracion(data);
  renderJerarquia(data);
  renderEmpresa(data);
  renderNomina(data);
  renderAntigüedad(data);
  renderAltasBajas();
  renderRight(data);
  abClosePopover();
}
// rebuildAll con feedback visual — usado por cambios de filtro/tema/fuente
let _rebuildTimer = null;
function rebuildAllDeferred(label) {
  // Coalescing: si el usuario cambia varios filtros rápido, solo se ejecuta una vez
  if (_rebuildTimer) clearTimeout(_rebuildTimer);
  showLoading(label || 'Aplicando filtros…');
  _rebuildTimer = setTimeout(() => {
    requestAnimationFrame(() => {
      try { rebuildAll(); } finally { hideLoading(); _rebuildTimer = null; }
    });
  }, 30);
}

// ══ KPIs ══
function renderKPIs(data) {
  setText('kTotal', data.length);
  setText('kH', data.filter(r=>norm(r['GENERO'])==='H').length);
  setText('kM', data.filter(r=>norm(r['GENERO'])==='M').length);

  const yr = new Date().getFullYear();
  setText('kAltasYr', yr);
  setText('kBajasYr', yr);

  // Aplica filtros del topbar a la unión de ambos archivos (usando rx*)
  const fS = document.getElementById('fSede').value;
  const fG = document.getElementById('fGen').value;
  const fE = document.getElementById('fEmp').value;
  const fN = document.getElementById('fGenero').value;
  const fH = document.getElementById('fHRBP').value;
  const fAr = document.getElementById('fArea').value;
  const matchFilters = (r) => {
    if (fS && rxSede(r) !== fS) return false;
    if (fG && rxGeneracion(r) !== fG) return false;
    if (fE && rxEmpresa(r) !== fE) return false;
    if (fN && norm(rxGet(r,'GENERO')) !== fN) return false;
    if (fH && rxHRBP(r) !== fH) return false;
    if (fAr && rxArea(r) !== fAr) return false;
    return true;
  };

  // Bajas del año: SOLO desde archivo de bajas (no usa rawData)
  let kB = 0;
  if (bajasData.length) {
    kB = bajasData.filter(matchFilters).filter(r => { const d = rxFechaBaja(r); return d && d.getFullYear() === yr; }).length;
  }
  setText('kBajas', kB);

  // Altas del año: SOLO desde rawData (activos). Si está en bajasData, ya no es alta.
  const seen = new Set();
  let kA = 0;
  const consider = (r) => {
    if (!matchFilters(r)) return;
    const di = rxFechaIngreso(r);
    if (!di || di.getFullYear() !== yr) return;
    const k = String(rxId(r) || rxNombre(r));
    if (seen.has(k)) return;
    seen.add(k);
    kA++;
  };
  rawData.forEach(consider);
  setText('kAltas', kA);
}
function abGetFiltered() {
  // Como renderKPIs pero sin filtro ACTIVO (bajas no son activas)
  const fS = document.getElementById('fSede').value;
  const fG = document.getElementById('fGen').value;
  const fE = document.getElementById('fEmp').value;
  const fN = document.getElementById('fGenero').value;
  const fH = document.getElementById('fHRBP').value;
  const fAr = document.getElementById('fArea').value;
  return rawData.filter(r => {
    if (fS && norm(r['SEDE'])       !== fS) return false;
    if (fG && norm(r['GENERACION']) !== fG) return false;
    if (fE && norm(r['EMPRESA'])    !== fE) return false;
    if (fN && norm(r['GENERO'])     !== fN) return false;
    if (fH && rxHRBP(r)             !== fH) return false;
    if (fAr && norm(r['AREA'])      !== fAr) return false;
    return true;
  });
}
function abYearOf(r, field) {
  const v = field === 'FECHA_INGRESO' ? (r[field] || r['Personalizado']) : r[field];
  const d = pDate(v);
  return d ? d.getFullYear() : null;
}
function renderSidebar(data) {
  const total = data.length;
  const c = countBy(data,'NIVEL_JERARQUIA');
  setText('sDireccion',    c['DIRECCION']||0);
  setText('sSubdireccion', c['SUBDIRECCION']||0);
  setText('sGerencia',     c['GERENCIA']||0);
  setText('sSupLider',     (c['SUPERVISION']||0)+(c['SUPERVISOR LIDER']||0));
  setText('sOperacion',    (c['OPERACION']||0)+(c['OPERATIVO']||0));
  // % Género
  const h = data.filter(r=>norm(r['GENERO'])==='H').length;
  const m = data.filter(r=>norm(r['GENERO'])==='M').length;
  setText('sPctH', total>0 ? Math.round(h/total*100)+'%' : '–');
  setText('sPctM', total>0 ? Math.round(m/total*100)+'%' : '–');
  // Altas por año (sobre rawData filtrado por ACTIVO)
  const fS=document.getElementById('fSede').value;
  const fG=document.getElementById('fGen').value;
  const fE=document.getElementById('fEmp').value;
  const fN=document.getElementById('fGenero').value;
  const fH=document.getElementById('fHRBP').value;
  const fAr=document.getElementById('fArea').value;
  const base = rawData.filter(r=>{
    if(norm(r['ESTATUS_COLABORADOR'])!=='ACTIVO') return false;
    if(fS && norm(r['SEDE'])!==fS) return false;
    if(fG && norm(r['GENERACION'])!==fG) return false;
    if(fE && norm(r['EMPRESA'])!==fE) return false;
    if(fN && norm(r['GENERO'])!==fN) return false;
    if(fH && rxHRBP(r)!==fH) return false;
    if(fAr && norm(r['AREA'])!==fAr) return false;
    return true;
  });
  const a24 = base.filter(r=>{ const d=pDate(r['FECHA_INGRESO']||r['Personalizado']); return d&&d.getFullYear()===2024; }).length;
  const a25 = base.filter(r=>{ const d=pDate(r['FECHA_INGRESO']||r['Personalizado']); return d&&d.getFullYear()===2025; }).length;
  setText('sAltas24', a24);
  setText('sAltas25', a25);
}

// ══ HC GENERAL POR MES ══
function renderGeneralMes(data) {
  const d = gd(); const months = last13();
  // Aplica filtros activos sobre rawData para calcular histórico filtrado
  const fS = document.getElementById('fSede').value;
  const fG = document.getElementById('fGen').value;
  const fE = document.getElementById('fEmp').value;
  const fN = document.getElementById('fGenero').value;
  const fH = document.getElementById('fHRBP').value;
  const fAr = document.getElementById('fArea').value;
  const baseData = rawData.filter(r => {
    if (norm(r['ESTATUS_COLABORADOR']) !== 'ACTIVO') return false;
    if (fS && norm(r['SEDE'])       !== fS) return false;
    if (fG && norm(r['GENERACION']) !== fG) return false;
    if (fE && norm(r['EMPRESA'])    !== fE) return false;
    if (fN && norm(r['GENERO'])     !== fN) return false;
    if (fH && rxHRBP(r)             !== fH) return false;
    if (fAr && norm(r['AREA'])      !== fAr) return false;
    return true;
  });
  const values = months.map(({year,month}) => {
    const eom = new Date(year,month+1,0);
    return baseData.filter(r=>isActiveAt(r,eom)).length;
  });
  destroyC('chGeneral');
  charts['chGeneral'] = new Chart(document.getElementById('chGeneral'), {
    type:'line',
    data:{
      labels: months.map(m=>fmtM(m.year,m.month)),
      datasets:[{
        data:values, borderColor:'#3b82f6', borderWidth:2.5,
        backgroundColor:'rgba(59,130,246,0.12)', fill:true, tension:0.35,
        pointBackgroundColor:'#fff', pointBorderColor:'#3b82f6',
        pointBorderWidth:2.5, pointRadius:5, pointHoverRadius:7,
        datalabels:{
          color: d.label, font:{size:fs(11),weight:'600'},
          anchor:'top', align:'top', offset:4,
          formatter: v => v > 0 ? v : ''
        }
      }]
    },
    options:{
      responsive:true, maintainAspectRatio:false,
      layout:{padding:{top:20, right:24, left:4, bottom:4}},
      plugins:{legend:{display:false},
        tooltip:{
          padding:10, displayColors:false,
          callbacks:{
            label: c => {
              const i = c.dataIndex;
              const hc = c.parsed.y;
              const {year, month} = months[i];
              const maxHC = Math.max(...values);
              const pctMax = maxHC ? Math.round(hc/maxHC*100) + '%' : '–';
              const ms = buildMonthStats(year, month, baseData);
              const lines = [
                ` HC: ${hc} personas`,
                ` % vs máx periodo: ${pctMax}`,
                ` Altas del mes: +${ms.altas}`,
                ` Bajas del mes: -${ms.bajas}`
              ];
              if (i > 0) {
                const delta = hc - values[i-1];
                const arrow = delta > 0 ? '↑' : delta < 0 ? '↓' : '=';
                lines.push(` Δ vs mes previo: ${arrow} ${Math.abs(delta)}`);
              }
              return lines;
            }
          }
        }
      },
      scales:{
        x:{grid:{color:d.grid}, ticks:{color:d.tick, font:{size:fs(9.5)}}},
        y:{grid:{color:d.grid}, ticks:{color:d.tick, font:{size:fs(9)}}, beginAtZero:false}
      }
    }
  });
}

// ══ HC POR SEDE ══
function renderHCSede(data) {
  const d = gd(); const months = last13();
  // Aplica filtros activos para calcular histórico por sede filtrado
  const fS = document.getElementById('fSede').value;
  const fG = document.getElementById('fGen').value;
  const fE = document.getElementById('fEmp').value;
  const fN = document.getElementById('fGenero').value;
  const fH = document.getElementById('fHRBP').value;
  const fAr = document.getElementById('fArea').value;
  const baseData = rawData.filter(r => {
    if (norm(r['ESTATUS_COLABORADOR']) !== 'ACTIVO') return false;
    if (fS && norm(r['SEDE'])       !== fS) return false;
    if (fG && norm(r['GENERACION']) !== fG) return false;
    if (fE && norm(r['EMPRESA'])    !== fE) return false;
    if (fN && norm(r['GENERO'])     !== fN) return false;
    if (fH && rxHRBP(r)             !== fH) return false;
    if (fAr && norm(r['AREA'])      !== fAr) return false;
    return true;
  });
  const SEDE_ORDER = ['CEDIS','INTERLOMAS','MANCERA','ROM','ROMERO'];
  const sedes = SEDE_ORDER.filter(s => baseData.some(r=>norm(r['SEDE'])===s));
  // Pre-calcular totales por mes para la etiqueta encima
  const totalesMes = months.map(({year,month}) => {
    const eom = new Date(year,month+1,0);
    return baseData.filter(r=>isActiveAt(r,eom)).length;
  });
  destroyC('chSede');
  charts['chSede'] = new Chart(document.getElementById('chSede'), {
    type:'bar',
    data:{
      labels: months.map(m=>fmtM(m.year,m.month)),
      datasets: sedes.map((s, si) => {
        const isTop = si === sedes.length - 1; // último dataset = encima
        return {
          label: s,
          backgroundColor: getC(C_SEDE,s),
          data: months.map(({year,month}) => {
            const eom = new Date(year,month+1,0);
            return baseData.filter(r=>norm(r['SEDE'])===s && isActiveAt(r,eom)).length;
          }),
          borderRadius: isTop ? 3 : 0,
          borderSkipped: false,
          datalabels:{
            color: '#fff',
            font:{size:fs(9), weight:'600'},
            anchor:'center', align:'center',
            formatter: v => v > 0 ? v : ''
          }
        };
      })
    },
    options:{
      responsive:true, maintainAspectRatio:false,
      layout:{padding:{top:24}},
      plugins:{
        legend:{position:'bottom',labels:{color:d.label,font:{size:fs(10)},boxWidth:11,padding:10}},
        // Plugin custom para total encima de cada barra
        tooltip:{
          padding:10, displayColors:true,
          callbacks:{
            title: items => items[0].label,
            label: item => {
              const sede = item.dataset.label;
              const {year, month} = months[item.dataIndex];
              const eom = new Date(year, month+1, 0);
              const rows = baseData.filter(r => norm(r['SEDE'])===sede && isActiveAt(r, eom));
              const totalMes = totalesMes[item.dataIndex];
              const pctMes = totalMes ? Math.round(rows.length/totalMes*100) + '%' : '–';
              const edad = ttFmtNum(ttProm(rows,'EDAD'),' años');
              const antig = ttFmtNum(ttAntigProm(rows),' años');
              const mix = ttMixHM(rows);
              const empDom = ttDom(rows,'EMPRESA');
              const lines = [` ${sede}: ${rows.length} (${pctMes} del mes)`];
              if (mix) lines.push(` ${mix}`);
              if (edad) lines.push(` Edad prom: ${edad}`);
              if (antig) lines.push(` Antig. prom: ${antig}`);
              if (empDom) lines.push(` Empresa top: ${empDom}`);
              return lines;
            }
          }
        }
      },
      scales:{
        x:{stacked:true, grid:{display:false}, ticks:{color:d.tick,font:{size:fs(9)}}},
        y:{stacked:true, grid:{color:d.grid}, ticks:{color:d.tick,font:{size:fs(9)}}}
      }
    },
    plugins:[{
      id:'sedeTotal',
      afterDatasetsDraw(chart) {
        const {ctx, data, scales:{x,y}} = chart;
        ctx.save();
        ctx.font = `bold 10px JetBrains Mono`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'bottom';
        totalesMes.forEach((total, i) => {
          if (!total) return;
          const xPos = x.getPixelForValue(i);
          const yPos = y.getPixelForValue(total) - 3;
          ctx.fillStyle = gd().txt;
          ctx.fillText(total, xPos, yPos);
        });
        ctx.restore();
      }
    }]
  });
}

