// ══ ALTAS Y BAJAS POR MES ══
function renderAltasBajas() {
  const d = gd();
  const yr = new Date().getFullYear();
  setText('chABYr', yr);

  // Filtros del topbar — aplicables a ambos archivos
  const fS = document.getElementById('fSede').value;
  const fG = document.getElementById('fGen').value;
  const fE = document.getElementById('fEmp').value;
  const fN = document.getElementById('fGenero').value;
  const fH = document.getElementById('fHRBP').value;
  const fAr = document.getElementById('fArea').value;
  const matchFilters = (r) => {
    if (fS && rxSede(r) !== fS) return false;
    if (fG && rxGeneracion(r) !== fG) return false;
    if (fE && rxEmpresa(r) !== fE) return false;
    if (fN && norm(rxGet(r, 'GENERO')) !== fN) return false;
    if (fH && rxHRBP(r) !== fH) return false;
    if (fAr && rxArea(r) !== fAr) return false;
    return true;
  };

  // ALTAS: SOLO desde rawData. Si está en bajasData, no se cuenta como alta.
  const altas = new Array(12).fill(0);
  const seenAltas = new Set();
  const considerAlta = (r) => {
    if (!matchFilters(r)) return;
    const fi = rxFechaIngreso(r);
    if (!fi || fi.getFullYear() !== yr) return;
    const k = String(rxId(r) || rxNombre(r));
    if (seenAltas.has(k)) return;
    seenAltas.add(k);
    altas[fi.getMonth()]++;
  };
  rawData.forEach(considerAlta);

  // BAJAS: solo desde el archivo de bajasData (rawData ya no contiene bajas)
  const bajas = new Array(12).fill(0);
  for (const r of bajasData) {
    if (!matchFilters(r)) continue;
    const fb = rxFechaBaja(r);
    if (!fb || fb.getFullYear() !== yr) continue;
    bajas[fb.getMonth()]++;
  }

  const lbls = ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];

  destroyC('chAltasBajas');
  charts['chAltasBajas'] = new Chart(document.getElementById('chAltasBajas'), {
    type:'bar',
    data:{
      labels: lbls,
      datasets:[
        { label:'Altas', backgroundColor:'#10B981', borderRadius:3, borderSkipped:false,
          data: altas,
          datalabels:{color:'#fff',font:{size:fs(10),weight:'700'},anchor:'center',align:'center',formatter:v=>v>0?v:''}
        },
        { label:'Bajas', backgroundColor:'#F59E0B', borderRadius:3, borderSkipped:false,
          data: bajas,
          datalabels:{color:'#fff',font:{size:fs(10),weight:'700'},anchor:'center',align:'center',formatter:v=>v>0?v:''}
        }
      ]
    },
    options:{
      responsive:true, maintainAspectRatio:false,
      layout:{padding:{top:8}},
      onClick(e, els) {
        if (!els.length) { abClosePopover(); return; }
        abShowPopover(els[0].index);
      },
      plugins:{
        legend:{position:'top',align:'end',labels:{color:d.label,font:{size:fs(10)},boxWidth:11,padding:10}},
        tooltip:{
          padding:10, displayColors:true,
          callbacks:{
            label: c => {
              const m = c.dataIndex;
              const cnt = c.parsed.y;
              const tipo = c.dataset.label;
              const lines = [` ${tipo} en ${lbls[m]} ${yr}: ${cnt}`];
              if (cnt > 0) lines.push(` Click en la barra para ver detalles`);
              return lines;
            }
          }
        }
      },
      scales:{
        x:{grid:{display:false},ticks:{color:d.tick,font:{size:fs(10)}}},
        y:{grid:{color:d.grid},ticks:{color:d.tick,font:{size:fs(9)},precision:0},beginAtZero:true}
      }
    }
  });
}
function abMonthOf(r, field) {
  const v = field === 'FECHA_INGRESO' ? (r[field] || r['Personalizado']) : r[field];
  const d = pDate(v);
  return d ? d.getMonth() : null;
}
function abShowPopover(monthIdx) {
  const pop = document.getElementById('abPopover');
  if (!pop) return;
  const yr = new Date().getFullYear();
  const lbls = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];

  // Filtros del topbar
  const fS = document.getElementById('fSede').value;
  const fG = document.getElementById('fGen').value;
  const fE = document.getElementById('fEmp').value;
  const fN = document.getElementById('fGenero').value;
  const fH = document.getElementById('fHRBP').value;
  const fAr = document.getElementById('fArea').value;
  const matchFilters = (r) => {
    if (fS && rxSede(r) !== fS) return false;
    if (fG && rxGeneracion(r) !== fG) return false;
    if (fE && rxEmpresa(r) !== fE) return false;
    if (fN && norm(rxGet(r, 'GENERO')) !== fN) return false;
    if (fH && rxHRBP(r) !== fH) return false;
    if (fAr && rxArea(r) !== fAr) return false;
    return true;
  };

  // ALTAS del mes: SOLO desde rawData (activos). Quien está en bajasData no es alta.
  const altas = [];
  const seenAltas = new Set();
  const considerAlta = (r, src) => {
    if (!matchFilters(r)) return;
    const fi = rxFechaIngreso(r);
    if (!fi || fi.getFullYear() !== yr || fi.getMonth() !== monthIdx) return;
    const k = String(rxId(r) || rxNombre(r));
    if (seenAltas.has(k)) return;
    seenAltas.add(k);
    altas.push({ r, src });
  };
  rawData.forEach(r => considerAlta(r, 'activos'));

  // BAJAS del mes: solo desde bajasData
  const bajas = [];
  for (const r of bajasData) {
    if (!matchFilters(r)) continue;
    const fb = rxFechaBaja(r);
    if (!fb || fb.getFullYear() !== yr || fb.getMonth() !== monthIdx) continue;
    bajas.push({ r, src: 'bajas' });
  }

  const renderGroup = (rows, kind) => {
    if (!rows.length) return '';
    const tag = kind === 'altas' ? 'ok' : 'off';
    const title = kind === 'altas' ? `Altas (${rows.length})` : `Bajas (${rows.length})`;
    const items = rows.map(({ r, src }) => {
      const arr = src === 'bajas' ? bajasData : rawData;
      const i = arr.indexOf(r);
      const full = rxNombre(r) || '(Sin nombre)';
      const puesto = rxPuesto(r);
      const sede = rxGet(r, 'SEDE') || '';
      const date = pdFmtDate(kind === 'altas' ? rxFechaIngreso(r) : rxFechaBaja(r)) || '';
      const meta = [puesto, sede, date].filter(Boolean).join(' · ');
      return `<div class="ab-pop-row" data-idx="${i}" data-src="${src}">
        <div class="ab-pop-row-name">${full.replace(/</g,'&lt;')}</div>
        <div class="ab-pop-row-meta">${meta.replace(/</g,'&lt;')}</div>
      </div>`;
    }).join('');
    return `<div class="ab-pop-group-title ${tag}">${title}</div>${items}`;
  };
  const body = (altas.length + bajas.length)
    ? renderGroup(altas,'altas') + renderGroup(bajas,'bajas')
    : '<div class="ab-pop-empty">Sin altas ni bajas en este mes.</div>';

  pop.innerHTML = `
    <div class="ab-pop-head">
      <div class="ab-pop-title">${lbls[monthIdx]} ${yr}</div>
      <div class="ab-pop-chips">
        <span class="ab-pop-chip ok">↑ ${altas.length}</span>
        <span class="ab-pop-chip off">↓ ${bajas.length}</span>
        <button type="button" class="ab-pop-x" onclick="abClosePopover()" title="Cerrar">&times;</button>
      </div>
    </div>
    <div class="ab-pop-body">${body}</div>
  `;
  pop.classList.remove('hidden');
  pop.classList.add('ab-popover');
  pop.querySelectorAll('.ab-pop-row').forEach(el => {
    el.addEventListener('click', () => {
      const idx = Number(el.getAttribute('data-idx'));
      const src = el.getAttribute('data-src');
      const arr = src === 'bajas' ? bajasData : rawData;
      const r = arr[idx];
      if (!r) return;
      pdRenderProfile(r, idx);
      document.getElementById('profileBackdrop').classList.add('open');
      const dr = document.getElementById('profileDrawer');
      dr.classList.add('open');
      dr.setAttribute('aria-hidden','false');
    });
  });
}
function abClosePopover() {
  const pop = document.getElementById('abPopover');
  if (pop) { pop.classList.add('hidden'); pop.classList.remove('ab-popover'); pop.innerHTML = ''; }
}

// ══ PROFILE DRAWER ══
let pdSelectedId = null;
let pdDebounce = null;

function pdNorm(v) {
  if (!v) return '';
  return String(v).normalize('NFD').replace(/[̀-ͯ]/g,'').toUpperCase().trim();
}

function pdFullName(r) {
  return rxNombre(r) || '(Sin nombre)';
}

function pdInitials(r) {
  const n = (rxGet(r, 'NOMBRE(S)', 'NOMBRES', 'NOMBRE') || '').toString().trim().charAt(0);
  const ap = (rxGet(r, 'A_PATERNO', 'APELLIDO PATERNO', 'APELLIDO_PATERNO') || '').toString().trim().charAt(0);
  if (n || ap) return (n + ap).toUpperCase();
  const full = pdFullName(r);
  return full.split(/\s+/).slice(0,2).map(p => p.charAt(0)).join('').toUpperCase() || '?';
}

function pdPhotoHTML(r, big) {
  const raw = (r['FOTO'] || '').toString().trim();
  const isUrl = /^(https?:\/\/|data:image\/|\/|\.\/)/i.test(raw);
  if (isUrl) {
    const safe = raw.replace(/"/g, '&quot;');
    return `<img src="${safe}" alt="Foto" onerror="this.replaceWith(Object.assign(document.createElement('span'),{textContent:'${pdInitials(r)}'}))"/>`;
  }
  return pdInitials(r);
}

function pdAntiguedad(r) {
  const ing = rxFechaIngreso(r);
  if (!ing) return null;
  const ref = rxFechaBaja(r) || new Date();
  let years = ref.getFullYear() - ing.getFullYear();
  let months = ref.getMonth() - ing.getMonth();
  if (ref.getDate() < ing.getDate()) months--;
  if (months < 0) { years--; months += 12; }
  if (years < 0) return null;
  const ys = years === 1 ? '1 año' : `${years} años`;
  const ms = months === 1 ? '1 mes' : `${months} meses`;
  if (years === 0) return ms;
  if (months === 0) return ys;
  return `${ys}, ${ms}`;
}

function pdFmtDate(v) {
  const d = pDate(v);
  if (!d) return null;
  return d.toLocaleDateString('es-MX', { day: '2-digit', month: 'short', year: 'numeric' });
}

function pdFmtMoney(v) {
  if (v == null || v === '') return null;
  const n = typeof v === 'number' ? v : Number(String(v).replace(/[^0-9.\-]/g,''));
  if (isNaN(n)) return String(v);
  return n.toLocaleString('es-MX', { style:'currency', currency:'MXN', maximumFractionDigits:0 });
}

function pdEmployeeId(r, idx) {
  const k = rxId(r);
  return k != null && k !== '' ? String(k) : `_idx_${idx}`;
}

function openProfileDrawer() {
  if (!rawData.length) { alert('Carga primero un archivo Excel.'); return; }
  document.getElementById('profileBackdrop').classList.add('open');
  const dr = document.getElementById('profileDrawer');
  dr.classList.add('open');
  dr.setAttribute('aria-hidden','false');
  setTimeout(() => { const i = document.getElementById('pdSearchInput'); if (i) i.focus(); }, 320);
}

function closeProfileDrawer() {
  document.getElementById('profileBackdrop').classList.remove('open');
  const dr = document.getElementById('profileDrawer');
  dr.classList.remove('open');
  dr.setAttribute('aria-hidden','true');
}

function pdClearSearch() {
  const i = document.getElementById('pdSearchInput');
  i.value = '';
  document.getElementById('pdSearchClear').classList.add('hidden');
  document.getElementById('pdResults').innerHTML = '';
  i.focus();
}

function pdSearch(query) {
  const q = pdNorm(query);
  const results = document.getElementById('pdResults');
  if (!q || q.length < 2) { results.innerHTML = ''; return; }
  const tokens = q.split(/\s+/).filter(Boolean);

  // Buscar en activos y bajas, deduplicando por ID_C. Activos va primero: si la misma persona
  // aparece en ambos archivos (p.ej. reingreso), gana su estatus vigente (ACTIVO) en vez de
  // mostrarla como BAJA y ocultar su registro activo.
  const MAX_MATCHES = 200;
  const seenIds = new Set();
  const matches = [];
  const considerArr = (arr, src) => {
    for (const r of arr) {
      if (matches.length >= MAX_MATCHES) break;
      const hay = r._nombreNorm || pdNorm(rxNombre(r)); // cache precomputado
      if (!tokens.every(t => hay.includes(t))) continue;
      const idc = String(rxId(r) || '');
      if (idc && seenIds.has(idc)) continue;
      if (idc) seenIds.add(idc);
      matches.push({ r, src });
    }
  };
  considerArr(rawData, 'activos');
  considerArr(bajasData, 'bajas');

  if (!matches.length) {
    results.innerHTML = '<div class="pd-res-empty">Sin coincidencias</div>';
    return;
  }
  const top = matches; // se muestran todas las coincidencias — el contenedor hace scroll
  const truncNote = matches.length >= MAX_MATCHES
    ? `<div class="pd-res-empty">Mostrando los primeros ${MAX_MATCHES} — afina tu búsqueda para ver menos resultados</div>`
    : '';
  results.innerHTML = top.map(({ r, src }, i) => {
    const full = rxNombre(r);
    const puesto = rxPuesto(r);
    const sede = rxGet(r, 'SEDE') || '';
    const meta = [puesto, sede].filter(Boolean).join(' · ') || '—';
    const est = rxEstatus(r);
    const chipCls = est === 'ACTIVO' ? 'pd-chip-mini ok' : 'pd-chip-mini off';
    return `<div class="pd-res-item" data-row="${i}" data-src="${src}">
      <div class="pd-res-avatar">${pdPhotoHTML(r, false)}</div>
      <div class="pd-res-info">
        <div class="pd-res-name">${full.replace(/</g,'&lt;')}</div>
        <div class="pd-res-meta">${meta.replace(/</g,'&lt;')}</div>
      </div>
      <span class="${chipCls}">${est}</span>
    </div>`;
  }).join('') + truncNote;
  results.querySelectorAll('.pd-res-item').forEach(el => {
    el.addEventListener('click', () => {
      const ri = Number(el.getAttribute('data-row'));
      const { r, src } = top[ri];
      const arr = src === 'bajas' ? bajasData : rawData;
      const idx = arr.indexOf(r);
      pdRenderProfile(r, idx);
      document.getElementById('pdResults').innerHTML = '';
    });
  });
}

function pdField(label, value, opts) {
  opts = opts || {};
  const empty = value == null || value === '' || (typeof value === 'string' && !value.trim());
  if (empty) {
    return { html: `<div class="pd-field"><div class="pd-field-lbl">${label}</div><div class="pd-field-val muted">—</div></div>`, filled: false };
  }
  const v = String(value).replace(/</g,'&lt;');
  const cls = opts.link ? 'pd-field-val link' : 'pd-field-val';
  const attr = opts.link ? ` data-link-jefe="${v.replace(/"/g,'&quot;')}"` : '';
  return { html: `<div class="pd-field"><div class="pd-field-lbl">${label}</div><div class="${cls}"${attr}>${v}</div></div>`, filled: true };
}

function pdSection(fields) {
  let filled = 0;
  const html = fields.map(f => { if (f.filled) filled++; return f.html; }).join('');
  return { html: `<div class="pd-grid">${html}</div>`, filled, total: fields.length };
}

function pdAcc(id, title, icon, section, openByDefault) {
  return `<div class="pd-acc${openByDefault ? ' open' : ''}" data-acc="${id}">
    <div class="pd-acc-head" onclick="pdToggleAcc('${id}')">
      <span class="pd-acc-caret">▼</span>
      <div class="pd-acc-title">${icon}${title}<span class="pd-acc-count">(${section.filled})</span></div>
    </div>
    <div class="pd-acc-body">${section.html}</div>
  </div>`;
}

function pdToggleAcc(id) {
  const el = document.querySelector(`#pdBody [data-acc="${id}"]`);
  if (el) el.classList.toggle('open');
}

function openListMode(kind, opts) {
  if (!rawData.length) { alert('Carga primero un archivo Excel.'); return; }
  opts = opts || {};
  const yr = opts.year != null ? opts.year : new Date().getFullYear();
  const isAltas = kind === 'altas';

  // Fuente: prioriza bajasData para bajas; para altas SOLO rawData (los que están en bajasData ya no son altas)
  let rows;
  if (isAltas) {
    const seen = new Set();
    rows = [];
    const consider = (r) => {
      const d = rxFechaIngreso(r);
      if (!d || d.getFullYear() !== yr) return;
      if (opts.month != null && d.getMonth() !== opts.month) return;
      const k = String(rxId(r) || rxNombre(r));
      if (seen.has(k)) return;
      seen.add(k);
      rows.push(r);
    };
    rawData.forEach(consider);
  } else {
    if (!bajasData.length) {
      showToast('<b>No hay archivo de bajas cargado</b><br/><small>Carga el Excel de bajas para ver el listado</small>', 'warn');
      return;
    }
    rows = bajasData.filter(r => {
      const d = rxFechaBaja(r);
      if (!d || d.getFullYear() !== yr) return false;
      if (opts.month != null && d.getMonth() !== opts.month) return false;
      return true;
    });
  }
  rows.sort((a,b) => {
    const da = isAltas ? rxFechaIngreso(a) : rxFechaBaja(a);
    const db = isAltas ? rxFechaIngreso(b) : rxFechaBaja(b);
    return (db||0) - (da||0);
  });

  // Abrir drawer + ocultar buscador, mostrar header de lista
  document.getElementById('profileBackdrop').classList.add('open');
  const dr = document.getElementById('profileDrawer');
  dr.classList.add('open');
  dr.setAttribute('aria-hidden','false');

  const monthLbl = opts.month != null
    ? ' · ' + ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'][opts.month]
    : '';
  const titleTxt = `${isAltas ? 'Altas' : 'Bajas'} ${yr}${monthLbl}`;

  const body = document.getElementById('pdBody');
  const items = rows.map((r, idx) => {
    const i = rawData.indexOf(r);
    const full = pdFullName(r);
    const puesto = (r['PUESTO_COLABORADOR']||'').toString().trim();
    const sede = (r['SEDE']||'').toString().trim();
    const date = pdFmtDate(field === 'FECHA_INGRESO' ? (r[field] || r['Personalizado']) : r[field]) || '—';
    const meta = [puesto, sede].filter(Boolean).join(' · ') || '—';
    return `<div class="pd-list-item" data-idx="${i}">
      <div class="pd-res-avatar">${pdPhotoHTML(r, false)}</div>
      <div class="pd-res-info">
        <div class="pd-res-name">${full.replace(/</g,'&lt;')}</div>
        <div class="pd-res-meta">${meta.replace(/</g,'&lt;')}</div>
      </div>
      <div class="pd-list-date ${isAltas ? 'ok' : 'off'}">${date}</div>
    </div>`;
  }).join('');

  body.innerHTML = `
    <div class="pd-list-head">
      <div class="pd-list-title">
        <span class="pd-list-chip ${isAltas ? 'ok' : 'off'}">${rows.length}</span>
        ${titleTxt}
      </div>
      <div class="pd-list-sub">${rows.length === 1 ? '1 colaborador' : rows.length + ' colaboradores'}</div>
    </div>
    ${rows.length ? `<div class="pd-list">${items}</div>` : '<div class="pd-res-empty">Sin registros para este periodo.</div>'}
  `;

  body.querySelectorAll('.pd-list-item').forEach(el => {
    el.addEventListener('click', () => {
      const idx = Number(el.getAttribute('data-idx'));
      pdRenderProfile(rawData[idx], idx);
    });
  });
}

// Abre el drawer en modo lista para cualquier grupo de colaboradores (p.ej. por nivel jerárquico)
