// ══ COSTOS DE LA ROTACIÓN ══
// Multiplicador de meses de sueldo por nivel jerárquico, según el modelo de costos de
// reemplazo de la empresa (a mayor seniority, mayor costo de reemplazo/reclutamiento).
const COSTO_ROT_MULT  = { OPERACION: 2.5, COORDINACION: 2.5, LIDER: 3.5, GERENCIA: 3.5, SUBDIRECCION: 4.5, DIRECCION: 5.5 };
const COSTO_ROT_ORDER = ['OPERACION', 'COORDINACION', 'LIDER', 'GERENCIA', 'SUBDIRECCION', 'DIRECCION'];
const COSTO_ROT_LBL   = { OPERACION:'Operación', COORDINACION:'Coordinación', LIDER:'Líder', GERENCIA:'Gerencia', SUBDIRECCION:'Subdirección', DIRECCION:'Dirección' };
// Agrupa el valor crudo de NIVEL_JERARQUIA en los 6 niveles de costo — mismos merges que
// usa el sidebar (Operación+Operativo, Supervisión+Supervisor Líder). A diferencia del
// sidebar, aquí sí se incluye Coordinación (×2.5, igual que Operación) para que el HC
// total siempre cuadre con el total real de bajas — en una tabla de costos no conviene
// dejar a nadie fuera silenciosamente.
function jerarquiaBucketCosto(nivelJer) {
  if (nivelJer === 'OPERACION' || nivelJer === 'OPERATIVO') return 'OPERACION';
  if (nivelJer === 'COORDINACION') return 'COORDINACION';
  if (nivelJer === 'SUPERVISION' || nivelJer === 'SUPERVISOR LIDER') return 'LIDER';
  if (nivelJer === 'GERENCIA') return 'GERENCIA';
  if (nivelJer === 'SUBDIRECCION') return 'SUBDIRECCION';
  if (nivelJer === 'DIRECCION') return 'DIRECCION';
  return null;
}
// ══ MOTIVOS DE SALIDA ══
// Pivot TIPO/MOTIVO × mes, del año seleccionado en el selector global "AÑO".
const MESES_UP = ['ENE','FEB','MAR','ABR','MAY','JUN','JUL','AGO','SEP','OCT','NOV','DIC'];
// Colapsa/expande las filas de motivo de un grupo (INVOLUNTARIA/VOLUNTARIA) al hacer
// clic en su fila de subtotal — el subtotal se queda visible siempre, solo se ocultan
// los renglones de detalle debajo.
function toggleMotivosGrupo(headEl) {
  const tipo = headEl.getAttribute('data-group-head');
  const collapsed = headEl.classList.toggle('collapsed');
  const tbody = headEl.closest('tbody');
  if (!tbody) return;
  tbody.querySelectorAll(`tr[data-group="${tipo}"]`).forEach(tr => {
    tr.style.display = collapsed ? 'none' : '';
  });
}

function renderMotivosSalida() {
  const t = document.getElementById('rotTablaMotivos');
  if (!t) return;
  setText('rotMotivosYrLbl', String(rotYearSelected));
  const bajas = bajasYearSrc(Number(rotYearSelected));
  const sum = arr => arr.reduce((a,b) => a + b, 0);
  const head = `<thead><tr><th>Tipo/Motivo</th>${MESES_UP.map(m => `<th class="num">${m}</th>`).join('')}<th class="num">Total</th></tr></thead>`;

  if (!bajas.length) {
    t.innerHTML = `${head}<tbody><tr class="empty-row"><td colspan="14">Sin bajas registradas en ${rotYearSelected}.</td></tr></tbody>`;
    return;
  }

  // Estructura: { TIPO: { motivo: [conteo x 12 meses] } }
  const tipos = { INVOLUNTARIA: {}, VOLUNTARIA: {}, 'SIN CLASIFICAR': {} };
  const totalPorMes = Array(12).fill(0);
  let totalGeneral = 0;
  for (const r of bajas) {
    const d = rxFechaBaja(r);
    if (!d) continue;
    const mes = d.getMonth();
    const tipo = isInvoluntaria(r) === true ? 'INVOLUNTARIA' : (isVoluntaria(r) === true ? 'VOLUNTARIA' : 'SIN CLASIFICAR');
    const motivo = norm(rxMotivoBaja(r)) || 'SIN MOTIVO';
    if (!tipos[tipo][motivo]) tipos[tipo][motivo] = Array(12).fill(0);
    tipos[tipo][motivo][mes]++;
    totalPorMes[mes]++;
    totalGeneral++;
  }

  const rowsHtml = [];
  ['INVOLUNTARIA', 'VOLUNTARIA', 'SIN CLASIFICAR'].forEach(tipo => {
    const motivos = tipos[tipo];
    const motivoKeys = Object.keys(motivos);
    if (!motivoKeys.length) return; // omitir el bloque si no hay bajas de ese tipo
    const tipoTotals = Array(12).fill(0);
    motivoKeys.forEach(m => motivos[m].forEach((v, i) => { tipoTotals[i] += v; }));
    // Colapsado por default — el usuario expande el detalle que le interese.
    rowsHtml.push(`<tr class="subtot collapsed" data-group-head="${tipo}" onclick="toggleMotivosGrupo(this)"><td><span class="motivo-chevron">▾</span>${tipo}</td>${tipoTotals.map(v => `<td class="num">${v || ''}</td>`).join('')}<td class="num">${sum(tipoTotals)}</td></tr>`);
    motivoKeys
      .sort((a, b) => sum(motivos[b]) - sum(motivos[a]))
      .forEach(m => {
        const arr = motivos[m];
        rowsHtml.push(`<tr data-group="${tipo}" style="display:none;"><td class="motivo-lbl">${m.replace(/</g,'&lt;')}</td>${arr.map(v => `<td class="num">${v || ''}</td>`).join('')}<td class="num">${sum(arr)}</td></tr>`);
      });
  });
  const totalRow = `<tr class="tot"><td>Total general</td>${totalPorMes.map(v => `<td class="num">${v || ''}</td>`).join('')}<td class="num">${totalGeneral}</td></tr>`;
  t.innerHTML = `${head}<tbody>${rowsHtml.join('')}${totalRow}</tbody>`;
}

function renderCostosRotacion() {
  const t = document.getElementById('rotTablaCostos');
  if (!t) return;
  setText('rotCostosYrLbl', String(rotYearSelected));
  // HC = bajas del año seleccionado por nivel jerárquico (no headcount activo total).
  const bajas = bajasYearSrc(Number(rotYearSelected));
  const grupos = {};
  COSTO_ROT_ORDER.forEach(k => { grupos[k] = { hc: 0, sueldo: 0 }; });
  for (const r of bajas) {
    const bucket = jerarquiaBucketCosto(rxNivelJer(r));
    if (!bucket) continue;
    grupos[bucket].hc++;
    grupos[bucket].sueldo += rxSueldo(r);
  }
  let totalHC = 0, totalSueldo = 0, totalCosto = 0;
  const rows = COSTO_ROT_ORDER.map(k => {
    const g = grupos[k];
    const costo = g.sueldo * COSTO_ROT_MULT[k];
    totalHC += g.hc; totalSueldo += g.sueldo; totalCosto += costo;
    return `<tr><td>${COSTO_ROT_LBL[k]}</td><td class="num">${g.hc}</td><td class="num">${pdFmtMoney(g.sueldo)}</td><td class="num">${pdFmtMoney(costo)}</td></tr>`;
  }).join('');
  const totalRow = `<tr class="tot"><td>Total</td><td class="num">${totalHC}</td><td class="num">${pdFmtMoney(totalSueldo)}</td><td class="num">${pdFmtMoney(totalCosto)}</td></tr>`;
  t.innerHTML = `<thead><tr><th>Jerarquía</th><th class="num">HC</th><th class="num">$ Sueldo mensual</th><th class="num">$ Rotación</th></tr></thead><tbody>${rows}${totalRow}</tbody>`;
}

function renderRotacionLider() {
  const sedeFilter = document.getElementById('rotLiderSede').value; // '' = todas
  const t = document.getElementById('rotTablaLider');
  const src = bajasSource();
  const hasVOLINV = hasTipoBajaData(src);

  // Bajas del año seleccionado en el selector global "AÑO" de Rotación
  let bajas = bajasYearSrc(Number(rotYearSelected));
  if (sedeFilter) bajas = bajas.filter(r => rxSede(r) === sedeFilter);

  // Agrupar por líder — la sede se asigna después, desde el registro propio del líder en
  // Activos (no la de sus subordinados dados de baja, que puede ser una sede distinta).
  const grupos = {};
  for (const r of bajas) {
    const jefe = rxJefe(r);
    if (!jefe) continue;
    if (!grupos[jefe]) grupos[jefe] = { jefe, sede: '—', inv:0, vol:0, desc:0, total:0 };
    if (isInvoluntaria(r) === true) grupos[jefe].inv++;
    else if (isVoluntaria(r) === true) grupos[jefe].vol++;
    else grupos[jefe].desc++;
    grupos[jefe].total++;
  }

  // Equipo actual por líder UNA SOLA VEZ (O(N) en vez de O(L×N)) — misma fórmula que
  // "Detalle por líder" del Resumen Ejecutivo: equipo actual + bajas = base, % = bajas÷base.
  // Reemplaza al promedio mensual (HC PROM), que se desplomaba a casi cero — y disparaba
  // la rotación a miles de % — en líderes con equipos chicos o de asignación reciente.
  const activosByLider = new Map();
  for (const r of rawData) {
    if (sedeFilter && rxSede(r) !== sedeFilter) continue;
    const j = rxJefe(r);
    if (!j) continue;
    if (!activosByLider.has(j)) activosByLider.set(j, []);
    activosByLider.get(j).push(r);
  }
  // Datos propios de cada líder (sede real) — un solo registro por nombre, tomado de Activos.
  const liderInfo = new Map();
  for (const r of rawData) {
    const nombre = norm(rxNombre(r));
    if (!liderInfo.has(nombre)) liderInfo.set(nombre, { sede: rxSede(r) || '—' });
  }
  Object.values(grupos).forEach(g => {
    g.team = (activosByLider.get(g.jefe) || []).length;
    g.pct = g.team > 0 ? (g.total / g.team * 100) : 0;
    const info = liderInfo.get(norm(g.jefe));
    if (info) g.sede = info.sede;
  });

  // Solo líderes que hoy siguen activos en la empresa — no tiene caso mostrar rotación
  // de un líder que él mismo ya causó baja.
  const filas = Object.values(grupos)
    .filter(g => liderInfo.has(norm(g.jefe)))
    .sort((a,b) => b.pct - a.pct);
  const showSedeCol = !sedeFilter; // si "todas las sedes", agrega columna Sede
  const colcount = (hasVOLINV ? 5 : 3) + 1 + (showSedeCol ? 1 : 0);

  if (!filas.length) {
    const sedeLbl = sedeFilter || 'todas las sedes';
    t.innerHTML = `<thead><tr><th>Líder</th>${showSedeCol ? '<th>Sede</th>' : ''}${hasVOLINV ? '<th class="num">INV</th><th class="num">VOL</th>' : ''}<th class="num">Total</th><th class="num">Equipo actual</th><th class="num">Rotación</th></tr></thead><tbody><tr class="empty-row"><td colspan="${colcount}">Sin bajas registradas en ${sedeLbl}.</td></tr></tbody>`;
    return;
  }
  const head = `<thead><tr><th>Líder</th>${showSedeCol ? '<th>Sede</th>' : ''}${hasVOLINV ? '<th class="num">INV</th><th class="num">VOL</th>' : ''}<th class="num">Total</th><th class="num">Equipo actual</th><th class="num">Rotación</th></tr></thead>`;
  const body = filas.map(g => {
    const lider = g.jefe.replace(/</g,'&lt;');
    const sedeCell = showSedeCol ? `<td>${g.sede.replace(/</g,'&lt;')}</td>` : '';
    const volInvCells = hasVOLINV
      ? `<td class="num">${g.inv}</td><td class="num">${g.vol}</td>`
      : '';
    return `<tr><td>${lider}</td>${sedeCell}${volInvCells}<td class="num">${g.total}</td><td class="num">${g.team}</td><td class="num pct">${g.pct.toFixed(0)}%</td></tr>`;
  }).join('');
  t.innerHTML = head + `<tbody>${body}</tbody>`;
}

// ══════════════════════════════════════════════════════════
// 📋 RESUMEN EJECUTIVO — Estilo corporativo
// ══════════════════════════════════════════════════════════
function renderResumenEjecutivo() {
  const yr = new Date().getFullYear();
  const today = new Date();
  const fechaCorta = today.toLocaleDateString('es-MX', { weekday:'long', day:'numeric', month:'long', year:'numeric' });
  setText('rxFecha', fechaCorta.charAt(0).toUpperCase() + fechaCorta.slice(1));
  setText('rxFooterFecha', today.toLocaleDateString('es-MX', { day:'2-digit', month:'long', year:'numeric' }));
  setText('rxBannerSub', `Año ${yr}`);
  setText('rxMkAltasLbl', `Altas ${yr}`);
  setText('rxMkBajasLbl', `Bajas ${yr}`);

  // Logo del banner — usa el logo blanco del PDF (LOGO_W) que ya existe
  const logoEl = document.getElementById('rxLogo');
  if (logoEl && typeof LOGO_W !== 'undefined') logoEl.src = LOGO_W;

  // ════ KPIs PRINCIPALES ════
  const hcTotal = rawData.length;
  let altasYTD = 0, bajasYTD = 0;
  const seenAlt = new Set();
  const altasYrRows = [];
  for (const r of rawData) {
    const fi = rxFechaIngreso(r);
    if (!fi || fi.getFullYear() !== yr) continue;
    const k = String(rxId(r) || rxNombre(r));
    if (seenAlt.has(k)) continue;
    seenAlt.add(k);
    altasYTD++; altasYrRows.push(r);
  }
  const bajasYrRows = [];
  for (const r of bajasData) {
    const fb = rxFechaBaja(r);
    if (!fb || fb.getFullYear() !== yr) continue;
    bajasYTD++; bajasYrRows.push(r);
  }
  const hcProm = hcPromMensual(rawData, yr);
  const rotPct = hcProm > 0 ? (bajasYTD / hcProm * 100) : 0;
  const retPct = Math.max(0, Math.min(100, 100 - rotPct));
  const fmt = (n) => n.toLocaleString('es-MX');
  setText('rxKHC', fmt(hcTotal));
  setText('rxKAltas', fmt(altasYTD));
  setText('rxKBajas', fmt(bajasYTD));
  setText('rxKRet', `${retPct.toFixed(1)}%`);
  setText('rxKRot', `${rotPct.toFixed(1)}%`);

  // ════ MINI-KPIs DEL BANNER (estilo PDF: Total/H/M/Altas/Bajas) ════
  const hombres = rawData.filter(r => norm(rxGet(r, 'GENERO')) === 'H').length;
  const mujeres = rawData.filter(r => norm(rxGet(r, 'GENERO')) === 'M').length;
  setText('rxMkTotal', fmt(hcTotal));
  setText('rxMkH', fmt(hombres));
  setText('rxMkM', fmt(mujeres));
  setText('rxMkAltas', fmt(altasYTD));
  setText('rxMkBajas', fmt(bajasYTD));

  // ════ PANORAMA — progress bars + estado ════
  setText('rxRetVal', `${retPct.toFixed(1)}%`);
  const retBar = document.getElementById('rxRetBar');
  if (retBar) retBar.style.width = `${retPct.toFixed(1)}%`;
  setText('rxRetSub', retPct >= 90 ? 'Retención excelente · objetivo cumplido'
                    : retPct >= 80 ? 'Retención saludable'
                    : retPct >= 70 ? 'A monitorear — revisar causas'
                    : 'Retención crítica — atención requerida');

  setText('rxRotVal', `${rotPct.toFixed(1)}%`);
  const rotBar = document.getElementById('rxRotBar');
  if (rotBar) {
    rotBar.style.width = `${Math.min(rotPct,100).toFixed(1)}%`;
    rotBar.classList.remove('rx-fill-cyan','rx-fill-amber','rx-fill-red');
    rotBar.classList.add(rotPct < 10 ? 'rx-fill-cyan' : rotPct < 20 ? 'rx-fill-amber' : 'rx-fill-red');
  }
  setText('rxRotSub', `${bajasYTD} bajas sobre HC prom ${hcProm.toFixed(0)}`);

  setText('rxStActivos', fmt(hcTotal));
  setText('rxStAltas', fmt(altasYTD));
  setText('rxStBajas', fmt(bajasYTD));

  // ════ DETECCIÓN DE ALERTAS ════
  // Agrupar bajas por líder
  const liderBajas = {};
  for (const r of bajasYrRows) {
    const j = rxJefe(r); if (!j) continue;
    if (!liderBajas[j]) liderBajas[j] = [];
    liderBajas[j].push(r);
  }
  // Activos por líder (para calcular rotación)
  const liderActivos = {};
  for (const r of rawData) {
    const j = rxJefe(r); if (!j) continue;
    if (!liderActivos[j]) liderActivos[j] = [];
    liderActivos[j].push(r);
  }

  const alerts = [];

  // 1) ADVERTENCIA: Líderes con rotación > 20%
  const liderRotacion = [];
  const allLideres = new Set([...Object.keys(liderBajas), ...Object.keys(liderActivos)]);
  for (const j of allLideres) {
    const team = liderActivos[j] || [];
    const teamSize = team.length;
    const bajas = (liderBajas[j] || []).length;
    const baseEquipo = teamSize + bajas;
    if (baseEquipo === 0) continue;
    const pct = baseEquipo > 0 ? (bajas / baseEquipo * 100) : 0;
    liderRotacion.push({ jefe: j, team: teamSize, baseEquipo, bajas, pct });
  }
  const highRot = liderRotacion.filter(l => l.pct > 20 && l.bajas >= 2).sort((a,b) => b.pct - a.pct);
  if (highRot.length > 0) {
    const rows = highRot.slice(0, 8).map(l =>
      `<tr><td>${escapeHTML(l.jefe)}</td><td class="num">${l.baseEquipo}</td><td class="num">${l.bajas}</td><td class="num rx-warn-cell">${l.pct.toFixed(0)}%</td></tr>`
    ).join('');
    alerts.push({
      level: 'warn',
      icon: '⚠️',
      title: `${highRot.length} líder${highRot.length>1?'es':''} con rotación elevada (&gt;20%)`,
      head: '<tr><th>Líder</th><th class="num">Equipo</th><th class="num">Bajas</th><th class="num">% Rotación</th></tr>',
      body: rows
    });
  }

  // 2) ATENCIÓN: Bajas del último mes
  const lastMonthStart = new Date(today.getFullYear(), today.getMonth(), 1);
  const recentBajas = bajasYrRows.filter(r => {
    const fb = rxFechaBaja(r); return fb && fb >= lastMonthStart;
  }).sort((a,b) => rxFechaBaja(b) - rxFechaBaja(a));
  if (recentBajas.length > 0) {
    const rows = recentBajas.slice(0, 8).map(r => {
      const nombre = rxNombre(r) || '(sin nombre)';
      const sede = rxSede(r) || '—';
      const fb = rxFechaBaja(r);
      const fecha = fb ? fb.toLocaleDateString('es-MX', { day:'2-digit', month:'short' }) : '—';
      const motivo = rxMotivoBaja(r) || '—';
      return `<tr><td>${escapeHTML(nombre)}</td><td>${escapeHTML(sede)}</td><td>${fecha}</td><td>${escapeHTML(motivo)}</td></tr>`;
    }).join('');
    alerts.push({
      level: 'info',
      icon: 'ℹ️',
      title: `${recentBajas.length} baja${recentBajas.length>1?'s':''} en el último mes`,
      head: '<tr><th>Colaborador</th><th>Sede</th><th>Fecha</th><th>Motivo</th></tr>',
      body: rows
    });
  }

  // 3) CRÍTICO: Bajas con menos de 30 días de antigüedad (early churn)
  const earlyChurn = bajasYrRows.filter(r => {
    const fi = rxFechaIngreso(r), fb = rxFechaBaja(r);
    if (!fi || !fb) return false;
    const days = (fb - fi) / (1000*60*60*24);
    return days >= 0 && days < 30;
  }).sort((a,b) => rxFechaBaja(b) - rxFechaBaja(a));
  if (earlyChurn.length > 0) {
    const rows = earlyChurn.slice(0, 8).map(r => {
      const nombre = rxNombre(r) || '(sin nombre)';
      const sede = rxSede(r) || '—';
      const fi = rxFechaIngreso(r), fb = rxFechaBaja(r);
      const days = Math.round((fb - fi) / (1000*60*60*24));
      const fechaI = fi ? fi.toLocaleDateString('es-MX', { day:'2-digit', month:'short', year:'2-digit' }) : '—';
      const fechaB = fb ? fb.toLocaleDateString('es-MX', { day:'2-digit', month:'short', year:'2-digit' }) : '—';
      return `<tr><td>${escapeHTML(nombre)}</td><td>${fechaI}</td><td>${fechaB}</td><td class="num rx-warn-cell">${days} d</td></tr>`;
    }).join('');
    alerts.push({
      level: 'danger',
      icon: '🔴',
      title: `${earlyChurn.length} colaborador${earlyChurn.length>1?'es':''} con menos de 30 días antes de baja`,
      head: '<tr><th>Colaborador</th><th>Ingreso</th><th>Baja</th><th class="num">Días</th></tr>',
      body: rows
    });
  }

  // Pintar alertas
  setText('rxAlertsCount2', `(${alerts.length})`);
  const alertsEl = document.getElementById('rxAlerts');
  if (alertsEl) {
    if (alerts.length === 0) {
      alertsEl.innerHTML = `<div class="rx-card" style="text-align:center;color:#94A3B8;padding:24px;">
        ✅ Sin alertas en este periodo — todo dentro de parámetros normales.
      </div>`;
    } else {
      alertsEl.innerHTML = alerts.map(a => `
        <div class="rx-alert rx-alert-${a.level}">
          <div class="rx-alert-head">
            <span class="rx-badge rx-badge-${a.level === 'warn' ? 'warn' : a.level === 'info' ? 'info' : 'danger'}">${a.level === 'warn' ? 'Advertencia' : a.level === 'info' ? 'Atención' : 'Crítico'}</span>
            <div class="rx-alert-title">${a.title}</div>
          </div>
          <table class="rx-mini-table">
            <thead>${a.head}</thead>
            <tbody>${a.body}</tbody>
          </table>
        </div>
      `).join('');
    }
  }

  // ════ ANÁLISIS DE LIDERAZGO ════
  // Solo líderes con equipo real (>= 3 activos) para que el ranking sea significativo
  const liderRanking = liderRotacion.filter(l => l.baseEquipo >= 3);
  const bestRet = [...liderRanking].sort((a,b) => a.pct - b.pct).slice(0, 5);
  const worstRet = [...liderRanking].filter(l => l.bajas > 0).sort((a,b) => b.pct - a.pct).slice(0, 5);

  const renderRanking = (arr, kind) => {
    if (!arr.length) return '<div class="rx-rank-empty">Sin datos disponibles</div>';
    return arr.map((l, i) => {
      const retP = (100 - l.pct).toFixed(0);
      const cls = kind === 'best' ? '' : (l.pct > 25 ? 'bad' : l.pct > 15 ? 'warn' : '');
      const widthPct = kind === 'best' ? retP : Math.min(l.pct, 100);
      const valShown = kind === 'best' ? `${retP}%` : `${l.pct.toFixed(0)}%`;
      // Muestra la base real (n/N) junto al % — un 100% con 1/1 no dice lo mismo que con 10/10
      const countShown = kind === 'best' ? `${l.team}/${l.baseEquipo}` : `${l.bajas}/${l.baseEquipo}`;
      return `<div class="rx-rank-row">
        <span class="rx-rank-num">${i+1}</span>
        <span class="rx-rank-name" title="${escapeHTML(l.jefe)}">${escapeHTML(l.jefe)}</span>
        <span class="rx-rank-bar"><span class="rx-rank-bar-fill ${cls}" style="width:${widthPct}%"></span></span>
        <span class="rx-rank-pct ${cls}">${valShown}<small class="rx-rank-n">${countShown}</small></span>
      </div>`;
    }).join('');
  };
  document.getElementById('rxTopRetencion').innerHTML = renderRanking(bestRet, 'best');
  document.getElementById('rxBotRetencion').innerHTML = renderRanking(worstRet, 'worst');

  // Spotlights
  if (bestRet[0]) {
    const b = bestRet[0];
    setText('rxBestPM', b.jefe);
    setText('rxBestPMStat', `${b.team} activos · ${b.bajas} bajas · ${(100-b.pct).toFixed(0)}% retención`);
  } else { setText('rxBestPM', '—'); setText('rxBestPMStat', 'Sin datos suficientes'); }
  if (worstRet[0]) {
    const w = worstRet[0];
    setText('rxWorstPM', w.jefe);
    setText('rxWorstPMStat', `${w.team} activos · ${w.bajas} bajas · ${w.pct.toFixed(0)}% rotación`);
  } else { setText('rxWorstPM', '—'); setText('rxWorstPMStat', 'Sin datos suficientes'); }

  // ════ TABLA DETALLE POR LÍDER ════
  const allLiderArr = liderRotacion.filter(l => l.baseEquipo >= 1).sort((a,b) => b.pct - a.pct);
  const tEl = document.getElementById('rxLiderTable');
  if (tEl) {
    const head = '<thead><tr><th>Líder</th><th class="num">Equipo</th><th class="num">Bajas</th><th>Avance retención</th><th class="num">%</th></tr></thead>';
    const body = allLiderArr.slice(0, 50).map(l => {
      const retP = Math.max(0, 100 - l.pct);
      const cls = l.pct < 10 ? '' : l.pct < 20 ? 'warn' : 'bad';
      return `<tr>
        <td>${escapeHTML(l.jefe)}</td>
        <td class="num">${l.baseEquipo}</td>
        <td class="num">${l.bajas}</td>
        <td><span class="rx-mini-bar"><div class="${cls}" style="width:${retP.toFixed(0)}%"></div></span></td>
        <td class="num ${l.pct > 20 ? 'rx-warn-cell' : ''}">${l.pct.toFixed(0)}% rot</td>
      </tr>`;
    }).join('');
    tEl.innerHTML = head + `<tbody>${body || '<tr><td colspan="5" class="rx-empty">Sin datos disponibles</td></tr>'}</tbody>`;
  }
}

// Pequeño helper para escapar HTML en valores dinámicos
function escapeHTML(s) {
  return String(s == null ? '' : s)
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}

// Exportar Resumen Ejecutivo a PDF
async function exportResumenPDF() {
  if (typeof html2canvas === 'undefined' || typeof window.jspdf === 'undefined') {
    showToast('<b>Librerías PDF no cargadas</b><br/><small>Verifica conexión y recarga</small>', 'error');
    return;
  }
  const body = document.getElementById('resumenBody');
  if (!body) return;
  showLoading('Generando PDF…');
  try {
    // El reporte ejecutivo usa fondo light por diseño (look corporativo) — siempre blanco
    const canvas = await html2canvas(body, {
      backgroundColor: '#F1F5F9',
      scale: 2,
      useCORS: true,
      logging: false
    });
    const imgData = canvas.toDataURL('image/png');
    const { jsPDF } = window.jspdf;
    // A4 portrait: 210 × 297 mm
    const pdf = new jsPDF('p', 'mm', 'a4');
    const pageW = pdf.internal.pageSize.getWidth();
    const pageH = pdf.internal.pageSize.getHeight();
    const imgW = pageW - 16;
    const imgH = (canvas.height * imgW) / canvas.width;
    let y = 8;
    if (imgH < pageH - 16) {
      pdf.addImage(imgData, 'PNG', 8, y, imgW, imgH);
    } else {
      // Si excede una página, lo paginamos
      let remaining = imgH;
      let offset = 0;
      while (remaining > 0) {
        pdf.addImage(imgData, 'PNG', 8, y - offset, imgW, imgH);
        remaining -= (pageH - 16);
        offset += (pageH - 16);
        if (remaining > 0) { pdf.addPage(); y = 8; }
      }
    }
    const yr = new Date().getFullYear();
    const fechaStr = new Date().toISOString().slice(0,10);
    pdf.save(`Resumen_Ejecutivo_RH_${yr}_${fechaStr}.pdf`);
    showToast('<b>✓ PDF generado</b>', 'success');
  } catch (err) {
    console.error('Error generando PDF:', err);
    showToast(`<b>Error al generar PDF</b><br/><small>${err.message || err}</small>`, 'error');
  } finally {
    hideLoading();
  }
}

